  let P_i := intermediateEvaluationPoly 𝔽q β h_ℓ_add_R_rate ⟨↑i, ⋯⟩ coeffs;
  let f_i := fun x => Polynomial.eval (↑x) P_i;
  let f_i_plus_1 := fold 𝔽q β ⟨↑i, ⋯⟩ h_i_succ_lt f_i r_chal;
  let new_coeffs := fun j => (1 - r_chal) * coeffs ⟨↑j * 2, ⋯⟩ + r_chal * coeffs ⟨↑j * 2 + 1, ⋯⟩;
  let P_i_plus_1 := intermediateEvaluationPoly 𝔽q β h_ℓ_add_R_rate ⟨↑i + 1, ⋯⟩ new_coeffs;
  ∀ (y : ↥(sDomain 𝔽q β h_ℓ_add_R_rate ⟨↑i + 1, ⋯⟩)), f_i_plus_1 y = Polynomial.eval (↑y) P_i_plus_
